DO $$
BEGIN
    BEGIN
        ALTER TABLE medication_dispensing ADD CONSTRAINT uk_medication_dispensing_uuid UNIQUE (dispensing_uuid);
    EXCEPTION WHEN duplicate_table THEN
        -- Constraint already exists, ignore
        NULL;
    END;
END $$;

DO $$
BEGIN
    BEGIN
        ALTER TABLE medication_dispensing ADD CONSTRAINT uk_medication_dispensing_pharmacy_tx UNIQUE (pharmacy_transaction_id);
    EXCEPTION WHEN duplicate_table THEN
        -- Constraint already exists, ignore
        NULL;
    END;
END $$;

-- Add foreign key to batch_records if table exists
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'batch_records') THEN
        BEGIN
            ALTER TABLE medication_dispensing ADD CONSTRAINT fk_medication_dispensing_batch
            FOREIGN KEY (batch_id) REFERENCES batch_records(id);
        EXCEPTION WHEN duplicate_object THEN
            -- Constraint already exists, ignore
            NULL;
        END;
    END IF;
END $$;

-- Add foreign key to insured if table exists
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'insured') THEN
        BEGIN
            ALTER TABLE medication_dispensing ADD CONSTRAINT fk_medication_dispensing_insured
            FOREIGN KEY (insured_id) REFERENCES insured(id);
        EXCEPTION WHEN duplicate_object THEN
            -- Constraint already exists, ignore
            NULL;
        END;
    END IF;
END $$;

-- Add foreign key to dependants if table exists
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'dependants') THEN
        BEGIN
            ALTER TABLE medication_dispensing ADD CONSTRAINT fk_medication_dispensing_dependant
            FOREIGN KEY (dependant_id) REFERENCES dependants(id);
        EXCEPTION WHEN duplicate_object THEN
            -- Constraint already exists, ignore
            NULL;
        END;
    END IF;
END $$;
